--- DNS configuration ---
--- pc2/etc/bind/db.root
$TTL 3600
@ IN SOA a.root-servers. hostmaster.root. ( 1 3600 900 604800 300 )
@ IN NS a.root-servers.
a.root-servers. IN AAAA 2001:db8:1100::10
test. IN NS ns1.test.
test. IN NS ns2.test.
ns1.test. IN AAAA 2001:db8:1100:1::10
ns2.test. IN AAAA 2001:db8:1100:2::10
--- pc2/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion no;
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};
zone "." { type master; file "/etc/bind/db.root"; };
